const freshWordState=()=>({records:{},dailyGoal:10,level:0});
let wordState=freshWordState();try{const s=JSON.parse(localStorage.getItem(WORD_KEY)||'null');if(s&&s.records&&typeof s.records==='object')wordState=sanitizeWordState(s)}catch{}
if(![0,...WORD_LEVELS.map(([n])=>n)].includes(wordState.level))wordState.level=0;
let bank=[],bankMap=new Map(),bankStatus='idle',wordScope='all',wordQuery='',wordPos='',wordCategory='',wordFrequency='',wordSort='frequency-desc',wordPage=0,wordCurrent=null,wordTrail=[],wordSession=null;
let wordTopic='';
let wordDeck='general';const PAGE_SIZE=40;
const wordInDeck=(w,deck=wordDeck)=>deck==='slang'?w.collection==='slang':w.collection!=='slang'&&!w.generalHidden;
function setWordDeck(deck){wordDeck=deck;wordTopic='';wordScope='all';wordQuery='';wordPos='';wordCategory='';wordFrequency='';wordCurrent=null;wordTrail=[];wordSession=null;wordPage=0;render();window.scrollTo(0,0)}
function wordDeckSwitcher(){return `<div class="x-seg" role="tablist" aria-label="単語帳の種類">${[['general','一般の単語'],['slang','口語・スラング']].map(([d,t])=>`<button role="tab" aria-selected="${wordDeck===d}" onclick="setWordDeck('${d}')">${t}</button>`).join('')}</div>${wordDeck==='slang'?'<p class="x-note">一般の単語とは分けて出題します。口語・粗さは各項目に表示します。</p>':''}`}
const wordInLevel=w=>w.collection==='slang'||!wordState.level||w.studyRank<=wordState.level;
function setWordLevel(n){if(![0,...WORD_LEVELS.map(([n])=>n)].includes(n))return;wordState.level=n;saveWords();wordCurrent=null;wordTrail=[];wordSession=null;wordPage=0;render()}
function levelName(){const l=WORD_LEVELS.find(([n])=>n===wordState.level);return l?l[1]+l[0].toLocaleString()+'語':'すべて'}
function wordLevelPicker(){if(wordDeck==='slang')return '';const count=bank.filter(w=>wordInDeck(w,'general')).length;return `<div class="x-control x-levels"><span class="x-label" id="x-level-label">範囲</span><div class="x-chips" role="group" aria-labelledby="x-level-label">${[...WORD_LEVELS,[0,'全部']].map(([n,name])=>`<button aria-pressed="${wordState.level===n}" onclick="setWordLevel(${n})"><span>${name}</span><b>${(n||count).toLocaleString()}<small>語</small></b></button>`).join('')}</div></div>`}
